#!/usr/bin/env bash
# Claims for round 456 (STORE-2b-3c-2a). Prints one line per claim. Planning output (HEAD db95f40): claims-456-planning-output.txt; sketch output (scratch with sketch-456 applied): claims-456-sketch-output.txt.
S=${S:-/home/runner/czaba-project/store}; L=/home/runner/czaba-project/tmp/studio-real-loop; B=$L/b-round-455; H=$S/app/lib/__tests__
echo "K1 $(python3 -I -c "import json;g=json.load(open('$L/gates/gate-round-455.json'));print(g['status'],g['commit'][:7])")"
echo "K2 $(git -C $S rev-parse --short=7 HEAD) dirty=$(git -C $S status --short --untracked-files=all | wc -l)"
echo "K3 $(grep -c '^export function' $H/helpers/style-scan.ts) cssRuleBlocks=$(grep -c 'export function cssRuleBlocks' $H/helpers/style-scan.ts) reachable=$(grep -c 'export function reachableScripts' $H/helpers/style-scan.ts) resolvedImports=$(grep -c 'export function resolvedImports' $H/helpers/style-scan.ts)"
echo "K4 hitsByEnclosingRule=$(grep -c 'hitsByEnclosingRule' $H/store-live-teal.test.ts) TOP_LEVEL=$(grep -c 'TOP_LEVEL_' $H/store-live-teal.test.ts) lineCount=$(grep -c 'lineCount(' $H/store-live-teal.test.ts) its=$(grep -cE "^  it\('LT" $H/store-live-teal.test.ts) bracekeys=$(grep -cE "^  'styles/[^']* \{'" $H/store-live-teal.test.ts)"
echo "K5 ruleBodiesFor=$(grep -c 'ruleBodiesFor' $H/store-glow-shadow.test.ts) accent=$(grep -c 'shadow-glow(?:-accent)?(?!' $H/store-glow-shadow.test.ts) its=$(grep -cE "^  it\('GS" $H/store-glow-shadow.test.ts)"
echo "K6 $(cd $S/app && for t in hover-glow interactive-card audio-preview-inline-button audioPlayingPulse playButtonPulse is-playing product-detail-add-to-cart newsletter-button-large testimonial-card waveform-bar track-row-waveform loading-brand pack-card-3d about-image-overlay value-card glass-card; do printf '%s:%s ' $t "$(grep -rlE "(^|[^a-zA-Z0-9_-])$t([^a-zA-Z0-9_-]|$)" --include=*.ts --include=*.tsx . | grep -v __tests__ | sed 's#^\./##' | sort | tr '\n' ',')"; done)"
echo "K7 $(python3 -I $B/probe/reach.py $S components/product/TrackRow.tsx components/audio/WaveForm.tsx components/loading/TrackRowSkeleton.tsx components/loading/PianoLoadingAnimation.tsx components/studio/StemsLoadingAnimation.tsx components/audio/AudioPreviewButton.tsx | diff -q - $B/probe/reach-head.txt >/dev/null && echo reach-equal || echo reach-DIFF) $(python3 -I $B/probe/reach-wholebarrel.py $S components/product/TrackRow.tsx components/audio/WaveForm.tsx components/loading/TrackRowSkeleton.tsx components/loading/PianoLoadingAnimation.tsx components/home/ArtistBioSection.tsx | diff -q - $B/probe/wholebarrel-control.txt >/dev/null && echo control-equal || echo control-DIFF)"
K8F=$(grep -rl '<AudioPreviewButton' $S/app --include=*.tsx | grep -v __tests__ | sort)
echo "K8 default=$(grep -c "variant = 'overlay'" $S/app/components/audio/AudioPreviewButton.tsx) files=$(echo "$K8F" | sed "s#$S/app/##" | tr '\n' ',') tags=$(cat $K8F | grep -o '<AudioPreviewButton' | wc -l) overlay=$(cat $K8F | grep '<AudioPreviewButton' | grep -c 'variant="overlay"') spread=$(cat $K8F | grep '<AudioPreviewButton' | grep -c '{\.\.\.')"
echo "K9 $(grep -nE 'animation: (audioPlayingPulse|playButtonPulse)' $S/app/styles/app.css | cut -d: -f1 | tr '\n' ' ')$(awk 'NR==589||NR==748' $S/app/styles/app.css | tr '\n' '|')"
echo "K10 $(sed -n 4p $S/docs/implementation/2026/quarter-IV/298-saba-b-14-store-seek-thumb.md) | 299=$(ls $S/docs/implementation/2026/quarter-IV | grep -c '^299-')"
echo "K11 $(cd $B && sha256sum -c sketch-456.sha256 2>&1 | tail -1) $(test -f $B/sketch-review.md && grep -c "$(cut -c1-64 $B/sketch-456.sha256)" $B/sketch-review.md) $(wc -l < $B/mutants/mutants.txt) $(grep -c RED $B/mutants/mutants.txt)"
echo "K12 $(for f in probe/reach.py probe/reach-wholebarrel.py probe/reach-head.txt probe/wholebarrel-control.txt grants-456.txt covering-456.txt run-mutants.sh precheck-covering.log precheck-full-raw.log precheck-typecheck.log precheck-lint.log sketch-review.md sketch-files-sha256.txt sketch-456.sha256 claims-456-planning-output.txt claims-456-sketch-output.txt mutants/mutants.txt expect-counts.txt apply-check.txt precheck-biome-scoped.log ../b-round-455-checkpoint-request.md ../b-round-453/probe/c12-run/c12-from-c448.cjs ../b-round-448/probe/warm.cjs ../c-round-455/c12-tree.json; do test -f $B/$f && printf 1 || printf "0($f)"; done)"
echo "K13 $(cd $L && python3 -I tools/l58-check.py current-task.md | tail -1)"
echo "K14 media-artwork=$(grep -c '^  \.audio-player-artwork {$' $S/app/styles/app.css) top-artwork=$(grep -c '^\.audio-player-artwork {$' $S/app/styles/app.css)"
echo "K15 accent-hits=$(grep -rlE '(^|[^a-zA-Z0-9_-])shadow-glow-accent([^a-zA-Z0-9_-]|$)' $S/app $S/perf --include=*.ts --include=*.tsx --include=*.css 2>/dev/null | grep -v __tests__ | wc -l) theme-utility-hits=$(grep -rlE '(bg|text|border|ring|from|via|to|fill|stroke|shadow|outline)-(glow-primary|video-sync)|var\(--(color-glow-primary|color-video-sync|gradient-primary|gradient-hero|gradient-glow)' $S/app --include=*.ts --include=*.tsx | grep -v __tests__ | wc -l)"
echo "K16 $(awk '/^\.button-primary \{$/{f=1;next} f&&/^}/{f=0} f' $S/app/styles/app.css | tr -s ' ' | tr '\n' '|')"
echo "K17 $(for f in store-live-teal store-glow-shadow store-gradient-text store-teal-sweep; do printf '%s=%s ' $f $(grep -c 'expect(' $H/$f.test.ts); done)| saved: $(tr '\n' ' ' < $B/expect-counts.txt)"
echo "K18 $(tail -1 $B/apply-check.txt) $(tail -1 $B/precheck-biome-scoped.log) $(grep -c 'No fixes applied' $B/precheck-biome-scoped.log)"
